param([Parameter(Mandatory=$true)][ValidateSet('DebugCPU','ReleaseCPU','Debug','Release')][string]$Configuration,[switch]$ExecutionAuthorized)
# One component compile/link only; current r2 main objects, never a program or solver call.
$ErrorActionPreference='Stop';if(!$ExecutionAuthorized){throw 'Root full review and explicit build authorization required'}
$Configuration=@('DebugCPU','ReleaseCPU','Debug','Release')|Where-Object{$_ -ieq $Configuration};$gpu=$Configuration -in @('Debug','Release');$count=if($gpu){110}else{85};$tests=Split-Path -Parent $PSScriptRoot
$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$src=Join-Path $repo 'src';$logs=Join-Path $tests 'logs';$tag='upl_damp_component_'+$Configuration+'_r1';$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.helper.json')
$leaf=if($gpu){'upl_damp_gpu_r1'}else{'upl_damp_cpu_r1'};$cpp=Join-Path $PSScriptRoot ($leaf+'.cpp');$obj=Join-Path $folder 'helper.obj';$exe=Join-Path $folder ($leaf+'.exe');$dep=Join-Path $folder 'compile.dependencies.json'
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing bound Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function PassedCall($e){V @($e);$c=J $e.path;Need ($c.direct_native_call -and $c.typed_LASTEXITCODE_captured_immediately -and $c.owned_call_exited -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Actual immediate typed tool exit0 required';V @($c.program);if($c.log){V @($c.log)};return $c}
function Owned($tool,[string[]]$argv,[string]$suffix){
  $p=Join-Path $logs ($tag+'_'+$suffix+'.call.json');$log=Join-Path $logs ($tag+'_'+$suffix+'.log');Fresh @($p,$log);V @($tool);[IO.File]::WriteAllBytes($log,[byte[]]@());$start=[DateTime]::UtcNow.ToString('o');$code=$null;$why=$null;$saved=$ErrorActionPreference
  Push-Location $src;try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$why=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
  Save $p ([ordered]@{program=$tool;arguments=$argv;working_directory=$src;started_utc=$start;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$why;log=(E $log);build_tool_only=$true;program_run=$false;physical_acceptance=$false});return (E $p)
}
$paths=@($folder,$record);foreach($s in @('Compile','Link')){$paths+=@((Join-Path $logs ($tag+'_'+$s+'.call.json')),(Join-Path $logs ($tag+'_'+$s+'.log')))};Fresh $paths
$buildE=E (Join-Path $logs ('upl_damp_'+$Configuration+'_r2.build.json'));$b=J $buildE.path
Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq $Configuration -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and $b.runtime_unchanged -and $b.exact_object_basename_closure -and $b.objects_include_project_main -and @($b.objects).Count -eq ($count+1) -and @($b.source_snapshot).Count -eq 265 -and @($b.canonical_programs_before).Count -eq 7 -and @($b.runtime).Count -eq 4 -and !$b.program_or_component_run) 'Current passed r2 authoritative full build required'
$projectCall=PassedCall $b.project_call
$recipeLeaf=if($gpu){'upl_gpu_column_component_'+$Configuration+'_r2.helper.json'}elseif($Configuration -ceq 'DebugCPU'){'upl_case02_flux_affine_DebugCPU_r1.helper.json'}else{'upl_case02_flux_operator_ReleaseCPU_r1.helper.json'}
$recipeE=E (Join-Path $logs $recipeLeaf);$h=J $recipeE.path
Need ($h.passed -and $h.configuration -ceq $Configuration -and $h.exact_link_closure_verified -and @($h.objects).Count -eq $count -and $h.link_object_count -eq ($count+1) -and @($h.libraries).Count -eq $(if($gpu){7}else{17})) 'Actual same-configuration helper argument/library recipe required'
$cc=PassedCall $h.compile_call;$lc=PassedCall $h.link_call;Need ([IO.Path]::GetFileName($cc.program.path) -ieq 'cl.exe' -and [IO.Path]::GetFileName($lc.program.path) -ieq 'link.exe' -and $cc.working_directory -ieq $src -and $lc.working_directory -ieq $src) 'Real cl/link vectors with src working directory required';V @($cc.log,$lc.log)
$oldCpp=Join-Path $PSScriptRoot $(if($gpu){'upl_gpu_column_component_r2.cpp'}elseif($Configuration -ceq 'DebugCPU'){'upl_case02_flux_affine_r1.cpp'}else{'upl_case02_operator_r1.cpp'})
$neutralLeaf=if($gpu){'upl_gpu_observer_native_r1'}else{'upl_cpu_public_native_r1'};$neutralSha=if($gpu){'b112f7e78651dde136c2438a02f326522ef4cb35b5603fa1eb17ee24d3437857'}else{'9f6668bfe3d1bbcca7c45c58809f7062c21fcb46baae76f0a2a1b0ef3ca56d38'}
$authors=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_component_build_r1.json')),(E $cpp),(E (Join-Path $tests 'notes\upl_damp_components_r1.json')),(E (Join-Path $PSScriptRoot ($neutralLeaf+'.cpp'))),(E (Join-Path $tests ('notes\'+$neutralLeaf+'.json'))))
if($gpu){$authors+=@(E (Join-Path $PSScriptRoot 'upl_damp_cpu_r1.cpp'))};$neutral=@($authors|Where-Object{[IO.Path]::GetFileName($_.path) -ceq ($neutralLeaf+'.cpp')});Need ($neutral.Count -eq 1 -and $neutral[0].sha256 -ceq $neutralSha) 'Immutable neutral include identity differs'
$objects=@($b.objects|Where-Object{[IO.Path]::GetFileName($_.path) -ine 'main.obj'});$byName=@{};foreach($e in $objects){$name=[IO.Path]::GetFileName($e.path).ToLowerInvariant();Need (!$byName.ContainsKey($name)) 'Duplicate current object basename';$byName[$name]=$e};Need ($objects.Count -eq $count -and @($h.objects|Where-Object{[IO.Path]::GetFileName($_.path) -ieq 'main.obj'}).Count -eq 0) 'Exact non-main object scopes required'
$environmentE=$null;if($gpu){$environmentE=$b.environment;V @($environmentE);$environment=J $environmentE.path;Need ($environment.typed_LASTEXITCODE_captured_immediately -and $environment.owned_call_exited -and $environment.exit_code -is [int] -and $environment.exit_code -eq 0) 'Current r2 GPU developer environment required'}else{$environmentE=$h.environment_source;V @($environmentE);$environment=$h.environment;Need ($environment.exit_code -eq 0) 'Sealed CPU selected developer environment required'}
$selected=[ordered]@{};foreach($key in @('INCLUDE','LIB','VCToolsInstallDir','WindowsSdkDir','WindowsSDKVersion')){$v=[string]$environment.selected.$key;Need (![string]::IsNullOrWhiteSpace($v)) ('Missing selected environment: '+$key);$selected[$key]=$v};$environmentTools=@($environment.tools);if($gpu){$environmentTools=@($environment.program,$environment.script)}
$bindings=@($buildE,$b.project_call,$b.log,$b.program,$recipeE,$h.compile_call,$h.link_call,$cc.program,$lc.program,$cc.log,$lc.log,$environmentE)+$authors+@($b.inputs)+@($b.tools)+@($h.tools)+@($h.libraries)+@($b.objects)+$environmentTools
if(!$gpu){$bindings+=@($h.compiler_dependency_record)};$ca=@();$sources=0;$fo=0;$fd=0;$deps=0
foreach($a in $cc.arguments){if($a -ieq $oldCpp){$ca+=$cpp;$sources++}elseif($a.StartsWith('/Fo',[StringComparison]::OrdinalIgnoreCase)){$ca+='/Fo'+$obj;$fo++}elseif($a.StartsWith('/Fd',[StringComparison]::OrdinalIgnoreCase)){$ca+='/Fd'+(Join-Path $folder 'compile.pdb');$fd++}elseif(!$gpu -and $a -ieq $h.compiler_dependency_record.path){$ca+=$dep;$deps++}else{$ca+=$a}}
Need ($sources -eq 1 -and $fo -eq 1 -and $fd -eq 1 -and $deps -eq $(if($gpu){0}else{1}) -and $ca -ccontains '/std:c++17' -and $ca -ccontains '/fp:precise' -and $ca -ccontains $(if($Configuration -in @('DebugCPU','Debug')){'/MTd'}else{'/MT'})) 'Only declared source/Fo/Fd/dependency remaps with inherited flags allowed'
$la=@();$maps=@();$helpers=0;$outs=0;$pdbs=0
foreach($a in $lc.arguments){if($a -ieq $h.helper_object.path){$la+=$obj;$helpers++}elseif($a.StartsWith('/OUT:',[StringComparison]::OrdinalIgnoreCase)){$la+='/OUT:'+$exe;$outs++}elseif($a.StartsWith('/PDB:',[StringComparison]::OrdinalIgnoreCase)){$la+='/PDB:'+(Join-Path $folder 'link.pdb');$pdbs++}elseif($a.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)){$name=[IO.Path]::GetFileName($a).ToLowerInvariant();Need ($byName.ContainsKey($name)) ('Missing current object: '+$a);$la+=$byName[$name].path;$maps+=@{old_recipe_object=$a;current=$byName[$name]}}else{$la+=$a}}
$linked=@($la|Where-Object{$_.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)});Need ($helpers -eq 1 -and $outs -eq 1 -and $pdbs -eq $(if($Configuration -in @('DebugCPU','Debug')){1}else{0}) -and $maps.Count -eq $count -and $linked.Count -eq ($count+1) -and @($linked|Sort-Object -Unique).Count -eq ($count+1) -and @(Compare-Object ($linked|Sort-Object) ((@($objects.path)+@($obj))|Sort-Object)).Count -eq 0) 'Exact current non-main objects plus one new helper required'
function VerifyCurrent{
  V $bindings;V $b.canonical_programs_before;V $b.runtime_before
  foreach($p in @($b.source_snapshot)+@($b.documentation_snapshot,$b.case_readme_snapshot)){V @($p.original,$p.snapshot);Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256) 'Current original/snapshot differs'}
  $currentPaths=@(Get-ChildItem -LiteralPath (Join-Path $src 'source') -File|Where-Object{$_.Extension -in @('.cpp','.h','.cu','.cuh')}|ForEach-Object{$_.FullName});Need ($currentPaths.Count -eq 265 -and @(Compare-Object ($currentPaths|Sort-Object) ($b.source_snapshot.original.path|Sort-Object)).Count -eq 0) 'Current265 path membership differs'
  foreach($r in $b.runtime){V @($r.original,$r.copy)}
}
VerifyCurrent;foreach($key in $selected.Keys){[Environment]::SetEnvironmentVariable($key,[string]$selected[$key],'Process')};$env:PATH=([IO.Path]::GetDirectoryName($cc.program.path))+';'+$env:PATH
[void](New-Item -ItemType Directory -Path $folder);$compile=$null;$link=$null;$program=$null;$helperObject=$null;$dependencyE=$null;$runtime=@();$failure=$null
try{
  $compile=Owned $cc.program $ca 'Compile';[void](PassedCall $compile);$helperObject=E $obj
  if(!$gpu){$dependencyE=E $dep;$d=J $dep;$local=@($d.Data.Includes|Where-Object{$_.StartsWith($PSScriptRoot+'\',[StringComparison]::OrdinalIgnoreCase)});Need ($d.Data.Source -ieq $cpp -and $local.Count -eq 1 -and [IO.Path]::GetFileName($local[0]) -ceq ($neutralLeaf+'.cpp')) 'Actual CPU sourceDependencies neutral include closure differs'}
  VerifyCurrent;$link=Owned $lc.program $la 'Link';[void](PassedCall $link);$program=E $exe
  foreach($r in $b.runtime){$to=Join-Path $folder ([IO.Path]::GetFileName($r.copy.path));Fresh @($to);Copy-Item -LiteralPath $r.copy.path -Destination $to;$copy=E $to;Need ($copy.bytes -eq $r.copy.bytes -and $copy.sha256 -ieq $r.copy.sha256) 'New helper runtime copy differs';$runtime+=@{original=$r.copy;copy=$copy}}
}catch{$failure=$_.Exception.Message}
$unchanged=$false;try{VerifyCurrent;if($helperObject){V @($helperObject)};if($dependencyE){V @($dependencyE)};if($program){V @($program)};foreach($r in $runtime){V @($r.original,$r.copy)};if($compile){V @($compile)};if($link){V @($link)};$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
$passed=(!$failure -and $unchanged -and $null -ne $program -and $runtime.Count -eq 4)
Save $record ([ordered]@{stage='upl_damp_component_build_r1';passed=[bool]$passed;status=$(if($passed){'current_damping_component_linked_not_run'}else{'damping_component_build_failed_retained'});kind='component';fixture='Damping';backend=$(if($gpu){'GPU'}else{'CPU'});configuration=$Configuration;source_build=$buildE;source_snapshot=$b.source_snapshot;documentation_snapshot=$b.documentation_snapshot;case_readme_snapshot=$b.case_readme_snapshot;source_code_header_count=265;retained_compiler_recipe=$recipeE;environment_source=$environmentE;environment=@{selected=$selected;tools=$environmentTools};inputs=$bindings;tools=@($cc.program,$lc.program);libraries=$h.libraries;author_files=$authors;neutral_include=$neutral[0];objects=$objects;non_main_object_count=$count;helper_object=$helperObject;link_object_count=($count+1);exact_link_closure_verified=$true;object_substitutions=$maps;compile_call=$compile;link_call=$link;compiler_dependency_record=$dependencyE;GPU_sourceDependencies_added=$false;canonical_programs_before=$b.canonical_programs_before;canonical_runtime_before=$b.runtime_before;runtime=$runtime;program=$program;build_and_source_bindings_unchanged=$unchanged;failure=$failure;production_build_executed=$false;program_run=$false;solver_started=$false;canonical_program_installed=$false;physical_acceptance=$false})
if(!$passed){throw "Component build failed; retain artifacts and inspect $record"};Write-Output "One damping component linked, not run: $record"
